// Medya (MSE + HTMLMediaElement) uctan uca testi: gercek H.264/AAC fMP4 parcalari eklenir,
// oynatilir, aranir ve sonuna kadar oynatilir. Veriler: tests/js/media/*.mp4 (ffmpeg testsrc2, 2 sn).
// Calistirma: js_runner tests/js/media.js
var fails = [], count = 0, log = [];
function eq(a, b, m) { count++; if (a !== b) fails.push(m + ': ' + a + ' !== ' + b); }
function ok(c, m) { count++; if (!c) fails.push(m); }
function b64(s) { var bin = atob(s); var u = new Uint8Array(bin.length); for (var i = 0; i < bin.length; i++) u[i] = bin.charCodeAt(i); return u; }
var V = b64(""), AU = b64(""), P = b64("");

// --- statik ---
eq(MediaSource.isTypeSupported('video/mp4; codecs="avc1.4d401f"'), true, 'avc1 destekli');
eq(MediaSource.isTypeSupported('audio/mp4; codecs="mp4a.40.2"'), true, 'aac destekli');
eq(MediaSource.isTypeSupported('video/webm; codecs="vp9"'), false, 'vp9 yok');
eq(MediaSource.isTypeSupported('video/mp4; codecs="av01.0.05M.08"'), false, 'av1 yok');
eq(MediaSource.isTypeSupported('audio/webm; codecs="opus"'), false, 'opus yok');
var probe = document.createElement('video');
eq(probe.canPlayType('video/mp4; codecs="avc1.42E01E, mp4a.40.2"'), 'probably', 'canPlayType kesin');
eq(probe.canPlayType('video/mp4'), 'maybe', 'canPlayType belki');
eq(probe.canPlayType('video/webm'), '', 'canPlayType webm');
eq(probe.readyState, 0, 'baslangic readyState');
eq(isNaN(probe.duration), true, 'baslangic sure NaN');
eq(probe.buffered.length, 0, 'baslangic tampon');
var threw = ''; try { probe.buffered.start(0); } catch (e) { threw = e.name; }
eq(threw, 'IndexSizeError', 'TimeRanges sinir hatasi');
threw = ''; try { probe.volume = 2; } catch (e) { threw = e.name; }
eq(threw, 'IndexSizeError', 'volume araligi');

// --- MSE ---
var v = document.createElement('video');
document.body.appendChild(v);
var ms = new MediaSource();
var ev = [];
['loadstart', 'durationchange', 'loadedmetadata', 'loadeddata', 'canplay', 'canplaythrough', 'play', 'playing', 'seeking', 'seeked', 'ended', 'pause', 'resize'].forEach(function (t) {
  v.addEventListener(t, function () { ev.push(t); });
});
var tu = 0; v.addEventListener('timeupdate', function () { tu++; });
var sbEv = [];
ms.addEventListener('sourceopen', function () {
  ev.push('sourceopen');
  eq(ms.readyState, 'open', 'sourceopen readyState');
  var sv = ms.addSourceBuffer('video/mp4; codecs="avc1.4d000b"');
  var sa = ms.addSourceBuffer('audio/mp4; codecs="mp4a.40.2"');
  eq(ms.sourceBuffers.length, 2, 'iki SourceBuffer');
  ms.duration = 2;
  threw = ''; try { sv.appendBuffer(V.subarray(0, 10)); sv.appendBuffer(V.subarray(10, 20)); } catch (e) { threw = e.name; }
  eq(threw, 'InvalidStateError', 'updating iken ikinci append');
  var step = 0;
  sv.addEventListener('updatestart', function () { sbEv.push('vs'); });
  sv.addEventListener('updateend', function () {
    sbEv.push('ve');
    step++;
    // baslatma kutusu yarim, sonra kalan parcalar (kutu sinirlarinda olmayan bolunme)
    if (step === 1) sv.appendBuffer(V.subarray(10, 4321));
    else if (step === 2) sv.appendBuffer(V.subarray(4321));
    else if (step === 3) { eq(sv.buffered.length, 1, 'video tampon araligi'); log.push('vb=' + sv.buffered.start(0).toFixed(2) + '-' + sv.buffered.end(0).toFixed(2)); maybeEnd(); }
  });
  sa.addEventListener('updateend', function () { log.push('ab=' + sa.buffered.start(0).toFixed(2) + '-' + sa.buffered.end(0).toFixed(2)); maybeEnd(); });
  sa.appendBuffer(AU);
  var ended = 0;
  function maybeEnd() {
    if (++ended < 2) return;
    ok(v.buffered.length === 1 && v.buffered.end(0) > 1.9, 'eleman tamponu ' + (v.buffered.length ? v.buffered.end(0) : '-'));
    ms.endOfStream();
    eq(ms.readyState, 'ended', 'endOfStream');
    ok(Math.abs(ms.duration - 2.04) < 0.05, 'sure tampon sonuna ayarlandi ' + ms.duration);
    var p = v.play();
    ok(p instanceof Promise, 'play Promise');
    p.then(function () { ev.push('play-resolved'); });
    setTimeout(phase2, 700);
  }
});
v.src = URL.createObjectURL(ms);
eq(v.networkState, 2, 'NETWORK_LOADING');

var t1 = 0;
function phase2() {
  t1 = v.currentTime;
  ok(t1 > 0.2, 'oynatma ilerliyor: ' + t1);
  eq(v.paused, false, 'oynuyor');
  eq(v.videoWidth + 'x' + v.videoHeight, '160x90', 'video boyutu');
  var q = v.getVideoPlaybackQuality();
  ok(q.totalVideoFrames > 3, 'kareler cozuldu: ' + q.totalVideoFrames);
  v.pause();
  var tp = v.currentTime;
  setTimeout(function () {
    ok(Math.abs(v.currentTime - tp) < 0.06, 'duraklatinca zaman durur ' + tp + ' ' + v.currentTime);
    v.addEventListener('seeked', function once() {
      v.removeEventListener('seeked', once);
      ok(Math.abs(v.currentTime - 1.2) < 0.05, 'arama hedefi ' + v.currentTime);
      eq(v.seeking, false, 'seeking bitti');
      v.addEventListener('ended', function () {
        eq(v.ended, true, 'ended');
        eq(v.paused, true, 'sonda duraklar');
        ok(v.currentTime > 1.95, 'sonda zaman ' + v.currentTime);
        phase3();
      });
      v.play();
    });
    v.currentTime = 1.2;
    eq(v.seeking, true, 'seeking basladi');
  }, 300);
}

// --- ilerlemeli (parcasiz MP4, Blob URL) ---
function phase3() {
  var pv = document.createElement('video');
  var pev = [];
  ['loadedmetadata', 'canplay', 'ended'].forEach(function (t) { pv.addEventListener(t, function () { pev.push(t); }); });
  pv.addEventListener('loadedmetadata', function () {
    ok(Math.abs(pv.duration - 2.04) < 0.06, 'ilerlemeli sure ' + pv.duration);
    eq(pv.videoWidth, 160, 'ilerlemeli genislik');
  });
  pv.addEventListener('ended', function () { finish(pev); });
  pv.muted = true;
  pv.src = URL.createObjectURL(new Blob([P], { type: 'video/mp4' }));
  pv.play();
}

var result = 'bekleniyor';
function finish(pev) {
  var want = ['loadstart', 'durationchange', 'loadedmetadata', 'loadeddata', 'canplay', 'canplaythrough', 'play', 'playing'];
  for (var i = 0; i < want.length; i++) ok(ev.indexOf(want[i]) >= 0, 'olay ' + want[i] + ' (' + ev.join(',') + ')');
  ok(ev.indexOf('loadedmetadata') < ev.indexOf('loadeddata'), 'loadedmetadata < loadeddata');
  ok(ev.indexOf('seeking') < ev.indexOf('seeked'), 'seeking < seeked');
  ok(ev.indexOf('pause') >= 0 && ev.indexOf('ended') > ev.indexOf('seeked'), 'pause/ended');
  ok(tu >= 2, 'timeupdate ' + tu);
  eq(sbEv.slice(0, 2).join(','), 'vs,ve', 'updatestart/updateend sirasi');
  eq(pev.join(','), 'loadedmetadata,canplay,ended', 'ilerlemeli olaylar');
  console.log(log.join(' ') + ' | ' + ev.join(','));
  result = fails.length ? 'HATALAR (' + fails.length + '/' + count + '):\n' + fails.join('\n') : 'TUM ' + count + ' TEST GECTI';
}
setTimeout(function () { if (result === 'bekleniyor') { fails.push('zaman asimi: ' + ev.join(',')); finish([]); } }, 15000);
